cnt() { b=$(grep -rlE -- "$1" test/behavior examples --include='*.rig' | wc -l); r=$(grep -rlE -- "$1" test/reject --include='*.rig' | wc -l); d=$(cat SPEC.md SYNTAX.md | grep -cE -- "$1"); printf "%-20s beh=%4s rej=%4s docs=%4s\n" "$2" $b $r $d; }
cnt '^\s*errdefer' errdefer; cnt '^\s*defer' defer; cnt 'extern ' extern; cnt '^\s*raw' raw; cnt '^\s*zig\b' zig-block; cnt '^test ' test-blocks; cnt 'Signal' Signal; cnt 'Box\[' Box; cnt '~[A-Za-z]' weak; cnt "^\s*[a-z_]+:\s*(while|for)" labels; cnt 'break [a-z0-9]' break-value; cnt ' if .* =>' match-guard; cnt '^\s*new ' new-shadow; cnt '\+%|-%|\*%' wrapping; cnt '<<|>>' shifts; cnt 'U128|I128' int128; cnt '\.(min|max)\b' minmax; cnt '\.read\[|\.write\[' bytes-rw; cnt '\[[a-zA-Z0-9]+ of ' fill-literal; cnt 'catch \|' catch-bind; cnt '\?\? (return|break|continue)' qq-jump; cnt 'for .* in <' for-consume; cnt 'for .* in !' for-write; cnt 'replace\(' replace; cnt 'swap\(' swap; cnt 'Cell' Cell; cnt 'while .* as ' while-as; cnt '^\s*else$' else-block; cnt '^use ' use; cnt '^pub ' pub; cnt '\*\|' owned-closure; cnt 'fun\(' fun-type; cnt '=!' fixed-binding; cnt '^error ' error-set; cnt ' and .* as ' joined-bind; cnt 'match <' match-consume; cnt 'match !' match-write; cnt 'sub .*\)!' fallible-sub; cnt 'F32|F16' f32; cnt '0x|0b|0o' radix; cnt 'expect-panic' expect-panic; cnt '\.get\(' get; cnt '\.pop\(' pop; cnt '\.clear\(' clear; cnt 'capacity:' vec-capacity; cnt 'label|outer:' labels2; cnt ' in [a-z]+\.\.' range-for; cnt '=> *$' match-block-arm; cnt 'drop\(' drop-decl; cnt '^\s*-[a-z]' drop-stmt; cnt '\bnot\b' not; cnt '\?\?' qq; cnt '[a-z)]\?$|[a-z)]\? ' opt-propagate
